RSpec.describe "forwarded Timekeeping setup helpers" do
  let(:helper_company) { create(:company) }
  let(:helper_actor) { create(:user, current_workspace_id: helper_company.id) }
  let(:helper_paul) do
    create(:user, first_name: "Paul", last_name: "Connors", email: "helper-paul@example.com",
                  current_workspace_id: helper_company.id)
  end
  let(:helper_project) do
    create(:project, name: "Website", billable: true, client: create(:client, company: helper_company, name: "Acme LLC"))
  end
  let(:helper_fake) { TimekeepingContract::FakeTimekeeping.new(token_public_key: timekeeping_key_pair.public_key) }
  let(:helper_import) { create(:data_import, company: helper_company, user: helper_actor) }

  before do
    create(:employment, company: helper_company, user: helper_actor)
    helper_actor.add_role :admin, helper_company
    create(:employment, company: helper_company, user: helper_paul)
    helper_import.file.attach(io: StringIO.new(<<~CSV), filename: "harvest.csv", content_type: "text/csv")
      Date,Client,Project,Hours,First Name,Last Name
      2026-01-05,Acme LLC,Website,1,Paul,Connors
      2026-01-06,Acme LLC,Website,2,Paul,Connors
    CSV
  end

  it "arrange_forwarded_timekeeping hands ownership to Timekeeping at generation 2 and routes a forwarded import to the fake" do
    arrange_forwarded_timekeeping(
      helper_fake, company: helper_company, users: { helper_actor => "admin", helper_paul => "employee" },
                   project: helper_project
    )

    ownership = TimekeepingOwnership.find(TimekeepingOwnership::SINGLETON_ID)
    expect(ownership).to have_attributes(owner: "timekeeping", generation: 2)
    expect(helper_fake.generation).to eq(2)

    expect do
      with_forwarded_timekeeping_env { Imports::HarvestTimeEntriesImporter.new(helper_import).process }
    end.not_to change(TimesheetEntry, :count)

    creates = helper_fake.requests.select { |request| request[:method] == "POST" }
    expect(creates.pluck(:path)).to eq(["/v1/companies/#{helper_company.id}/entries"] * 2)
    expect(creates.map { |request| request[:body]["user_id"] }).to all(eq(helper_paul.id))
    expect(helper_import.reload).to have_attributes(status: "completed", imported_rows: 2, failed_rows: 0)
  end
end

RSpec.describe "forwarded Timekeeping environment helper" do
  it "with_forwarded_timekeeping_env sets the Timekeeping base URL and signing key only inside its block" do
    base_url_env = Timekeeping::EntryApiClient::BASE_URL_ENV
    key_env = Timekeeping::UserToken::PRIVATE_KEY_ENV
    previous = { base_url_env => ENV.fetch(base_url_env, nil), key_env => ENV.fetch(key_env, nil) }
    seen = {}

    with_forwarded_timekeeping_env do
      seen[:default_url] = ENV.fetch(base_url_env, nil)
      seen[:key] = ENV.fetch(key_env, nil)
    end
    with_forwarded_timekeeping_env("http://other-timekeeping.test") do
      seen[:custom_url] = ENV.fetch(base_url_env, nil)
    end

    expect(seen[:default_url]).to eq("http://timekeeping.test")
    expect(seen[:custom_url]).to eq("http://other-timekeeping.test")
    expect(seen[:key]).to eq(timekeeping_key_pair.to_pem)
    expect(ENV.fetch(base_url_env, nil)).to eq(previous[base_url_env])
    expect(ENV.fetch(key_env, nil)).to eq(previous[key_env])
  end
end

RSpec.describe Imports::HarvestTimeEntriesImporter, "on the shared forwarded setup" do
  let(:shared_rerun_company) { create(:company) }
  let(:shared_rerun_actor) { create(:user, current_workspace_id: shared_rerun_company.id) }
  let(:shared_rerun_paul) do
    create(:user, first_name: "Paul", last_name: "Connors", email: "shared-rerun-paul@example.com",
                  current_workspace_id: shared_rerun_company.id)
  end
  let(:shared_rerun_project) do
    create(:project, name: "Website", billable: true, client: create(:client, company: shared_rerun_company, name: "Acme LLC"))
  end
  let(:shared_rerun_fake) { TimekeepingContract::FakeTimekeeping.new(token_public_key: timekeeping_key_pair.public_key) }
  let(:shared_rerun_import) { create(:data_import, company: shared_rerun_company, user: shared_rerun_actor) }

  before do
    create(:employment, company: shared_rerun_company, user: shared_rerun_actor)
    shared_rerun_actor.add_role :admin, shared_rerun_company
    create(:employment, company: shared_rerun_company, user: shared_rerun_paul)
    arrange_forwarded_timekeeping(
      shared_rerun_fake, company: shared_rerun_company,
                         users: { shared_rerun_actor => "admin", shared_rerun_paul => "employee" },
                         project: shared_rerun_project
    )
    shared_rerun_import.file.attach(io: StringIO.new(<<~CSV), filename: "harvest.csv", content_type: "text/csv")
      Date,Client,Project,Hours,First Name,Last Name,Billable?,Invoiced?,Notes
      2026-01-05,Acme LLC,Website,1.5,Paul,Connors,Yes,No,first row
      2026-01-06,Acme LLC,Website,2,Paul,Connors,Yes,No,second row
    CSV
  end

  # "Forwarded writes use an `Idempotency-Key` built from the data import id and a digest of the row, so rerunning a failed import does not duplicate rows it already forwarded."
  it "a forwarded rerun on the shared setup sends exactly two creates, retrying the first row first under its original key" do
    calls = 0
    allow_any_instance_of(Timekeeping::Gateway).to receive(:import).and_wrap_original do |original, *args, **kwargs|
      result = original.call(*args, **kwargs)
      calls += 1
      if calls == 1
        TimekeepingOwnership.find(TimekeepingOwnership::SINGLETON_ID).update_columns(generation: 3)
        shared_rerun_fake.generation = 3
      end
      result
    end
    post_keys = -> { shared_rerun_fake.requests.filter_map { |r| r[:headers]["Idempotency-Key"] if r[:method] == "POST" } }

    with_forwarded_timekeeping_env do
      expect { described_class.new(shared_rerun_import).process }.to raise_error(Timekeeping::Gateway::StaleGeneration)
    end
    first_run_keys = post_keys.call
    expect(first_run_keys.size).to eq(1)

    with_forwarded_timekeeping_env { described_class.new(shared_rerun_import.reload).process }
    rerun_keys = post_keys.call.drop(first_run_keys.size)

    expect(rerun_keys.size).to eq(2)
    expect(rerun_keys.uniq.size).to eq(2)
    expect(rerun_keys.first).to eq(first_run_keys.first)
    expect(shared_rerun_fake.outbox.map { |row| row["entry"]["id"] }.uniq.size).to eq(2)
    expect(shared_rerun_import.reload).to have_attributes(status: "completed", failed_rows: 0)
  end
end

