require "rails_helper"

RSpec.describe "forwarded Timekeeping setup helpers" do
  # Both variables must be set for a forwarded import: the base URL picks the service and the key
  # signs the user token. A helper that set only one, or leaked them past the block, would break
  # other examples that expect the legacy store.
  it "with_forwarded_timekeeping_env sets the base URL and signing key inside the block and restores both afterwards" do
    base_url_env = Timekeeping::EntryApiClient::BASE_URL_ENV
    key_env = Timekeeping::UserToken::PRIVATE_KEY_ENV
    previous = { base_url_env => ENV.fetch(base_url_env, nil), key_env => ENV.fetch(key_env, nil) }
    seen = nil

    with_forwarded_timekeeping_env do
      seen = { base_url_env => ENV.fetch(base_url_env, nil), key_env => ENV.fetch(key_env, nil) }
    end

    expect(FORWARDED_TIMEKEEPING_BASE_URL).to eq("http://timekeeping.test")
    expect(seen[base_url_env]).to eq("http://timekeeping.test")
    expect(seen[key_env]).to eq(timekeeping_key_pair.to_pem)
    expect(ENV.fetch(base_url_env, nil)).to eq(previous[base_url_env])
    expect(ENV.fetch(key_env, nil)).to eq(previous[key_env])

    with_forwarded_timekeeping_env("http://other-timekeeping.test") do
      expect(ENV.fetch(base_url_env, nil)).to eq("http://other-timekeeping.test")
    end
    expect(ENV.fetch(base_url_env, nil)).to eq(previous[base_url_env])
  end
end

