RSpec.describe "forwarded Timekeeping setup helpers" do
  let(:order_company) { create(:company) }
  let(:order_actor) { create(:user, current_workspace_id: order_company.id) }
  let(:order_paul) do
    create(:user, first_name: "Paul", last_name: "Connors", email: "order-paul@example.com",
                  current_workspace_id: order_company.id)
  end
  let(:order_project) do
    create(:project, name: "Website", billable: true, client: create(:client, company: order_company, name: "Acme LLC"))
  end
  let(:order_fake) { TimekeepingContract::FakeTimekeeping.new(token_public_key: timekeeping_key_pair.public_key) }
  let(:order_import) { create(:data_import, company: order_company, user: order_actor) }

  before do
    create(:employment, company: order_company, user: order_actor)
    order_actor.add_role :admin, order_company
    create(:employment, company: order_company, user: order_paul)
    arrange_forwarded_timekeeping(order_fake, company: order_company,
                                              users: { order_actor => "admin", order_paul => "employee" },
                                              project: order_project)
    order_import.file.attach(io: StringIO.new(<<~CSV), filename: "harvest.csv", content_type: "text/csv")
      Date,Client,Project,Hours,First Name,Last Name,Billable?,Invoiced?,Notes
      2026-01-05,Acme LLC,Website,1.5,Paul,Connors,Yes,No,first row
      2026-01-06,Acme LLC,Website,2,Paul,Connors,Yes,No,second row
    CSV
  end

  # The rerun example folded into the generation-change owner checked the rerun's POSTs in
  # request order: exactly two, unique, and the first reusing the first run's key. Grouping by
  # note alone would miss a rerun that sends the rows in another order or sends one twice.
  it "a forwarded rerun on the shared setup after a generation change sends exactly two creates, the first reusing the first run's key" do
    calls = 0
    allow_any_instance_of(Timekeeping::Gateway).to receive(:import).and_wrap_original do |original, *args, **kwargs|
      result = original.call(*args, **kwargs)
      calls += 1
      if calls == 1
        TimekeepingOwnership.find(TimekeepingOwnership::SINGLETON_ID).update_columns(generation: 3)
        order_fake.generation = 3
      end
      result
    end
    create_keys = lambda do
      order_fake.requests.filter_map { |request| request[:headers]["Idempotency-Key"] if request[:method] == "POST" }
    end

    with_forwarded_timekeeping_env do
      expect { Imports::HarvestTimeEntriesImporter.new(order_import).process }
        .to raise_error(Timekeeping::Gateway::StaleGeneration)
    end
    first_run_keys = create_keys.call
    expect(first_run_keys.size).to eq(1)

    with_forwarded_timekeeping_env { Imports::HarvestTimeEntriesImporter.new(order_import.reload).process }
    rerun_posts = order_fake.requests.select { |request| request[:method] == "POST" }.drop(first_run_keys.size)
    rerun_keys = rerun_posts.map { |request| request[:headers]["Idempotency-Key"] }

    expect(rerun_keys.size).to eq(2)
    expect(rerun_keys.uniq.size).to eq(2)
    expect(rerun_keys.first).to eq(first_run_keys.first)
    expect(rerun_posts.map { |request| request[:body]["note"] }).to eq(["first row", "second row"])
    expect(order_fake.outbox.map { |row| row["entry"]["id"] }.uniq.size).to eq(2)
    expect(order_import.reload).to have_attributes(status: "completed", failed_rows: 0)
  end
end

