require "rails_helper"

RSpec.describe "forwarded Timekeeping setup helpers" do
  # An import that raises StaleGeneration or OwnershipMoving inside the block must not leave the
  # private key or base URL set for the next example, or later legacy examples would forward by accident.
  it "puts both Timekeeping environment variables back when the forwarded block raises" do
    with_timekeeping_env(
      Timekeeping::UserToken::PRIVATE_KEY_ENV => "outer-key",
      Timekeeping::EntryApiClient::BASE_URL_ENV => "http://outer.test"
    ) do
      seen = {}
      expect do
        with_forwarded_timekeeping_env do
          seen[:base_url] = ENV.fetch(Timekeeping::EntryApiClient::BASE_URL_ENV, nil)
          seen[:private_key] = ENV.fetch(Timekeeping::UserToken::PRIVATE_KEY_ENV, nil)
          raise Timekeeping::Gateway::StaleGeneration
        end
      end.to raise_error(Timekeeping::Gateway::StaleGeneration)

      expect(seen).to eq(base_url: "http://timekeeping.test", private_key: timekeeping_key_pair.to_pem)
      expect(ENV.fetch(Timekeeping::EntryApiClient::BASE_URL_ENV, nil)).to eq("http://outer.test")
      expect(ENV.fetch(Timekeeping::UserToken::PRIVATE_KEY_ENV, nil)).to eq("outer-key")
    end
  end
end

require "rails_helper"

RSpec.describe "forwarded Timekeeping setup helpers" do
  let(:arrange_reset_company) { create(:company) }
  let(:arrange_reset_paul) { create(:user, current_workspace_id: arrange_reset_company.id) }
  let(:arrange_reset_project) do
    create(:project, billable: true, client: create(:client, company: arrange_reset_company))
  end
  let(:arrange_reset_fake) { TimekeepingContract::FakeTimekeeping.new(token_public_key: timekeeping_key_pair.public_key) }

  # Every copied setup this helper replaces set owner "timekeeping" with generation 2 on the ownership row
  # and on the fake, so a generation-bump example that starts from a leftover generation would not bump past it.
  it "resets ownership to timekeeping at generation 2 on both sides even when an earlier step left a later generation" do
    TimekeepingOwnership.find(TimekeepingOwnership::SINGLETON_ID).update_columns(owner: "monolith", generation: 7)
    arrange_reset_fake.generation = 7

    arrange_forwarded_timekeeping(
      arrange_reset_fake,
      company: arrange_reset_company,
      users: { arrange_reset_paul => "employee" },
      project: arrange_reset_project
    )

    ownership = TimekeepingOwnership.find(TimekeepingOwnership::SINGLETON_ID)
    expect(ownership).to have_attributes(owner: "timekeeping", generation: 2)
    expect(arrange_reset_fake.generation).to eq(2)
  end
end
